L={}
L[2]=dict(title="Get me set up",sub="Teach the plug-in who you are, one time. Every video after this already looks like you.",
 intro="Plan on 30 to 60 minutes. You answer a few questions, look at a few previews, and approve what gets saved. You only do this once.",
 steps=[
 ("1. Start with one sentence",["Tell your assistant: <b>Get me set up.</b> That is the whole command."]),
 ("2. Your business",["It asks for your brand name exactly as you want it on screen, a tagline if you have one, and in a sentence or two who your videos are for and what you help them with. It writes this down so it never has to ask again."]),
 ("3. Your logo",["The best file is a PNG with a transparent background, at least 1000 pixels wide. If your logo has a white box around it, your assistant tells you, and you can keep it or swap in a better file.","Copy the logo into your project's brand folder and tell your assistant the file name."]),
 ("4. Your colors",["You need three: a main color, a darker version, and your darkest one for backgrounds. They are written as hex codes, a pound sign and six characters.",
   ("table",[("Canva","Click a colored shape in a branded design. The code shows next to the color."),("Your website","Right-click a colored button, choose Inspect, and look for the code."),("Your logo","Give your assistant the logo and it suggests colors. They are only suggestions. Nothing is saved until you say yes.")])]),
 ("5. Your metallic finish",["Your videos have a thin metal trim on frames, lines and check marks. Choose gold, rose gold, silver or copper. Your assistant shows you the choices so you are not guessing from a word."]),
 ("6. Fonts",["Pick a pairing from the ones that come with the plug-in. If you have a brand font that is not on the list, tell your assistant. A custom font has to be added and tested, so it cannot be promised on the spot."]),
 ("7. Who is on screen",["Your face, an AI avatar of you made in another tool, a cartoon or 3D character you own, the built-in stick figure, or no one, just voiceover and graphics. You can pick more than one.","If you bring your own character art, make sure you own the rights to it."]),
 ("8. Your caption style",["Your assistant makes one image showing three caption styles side by side, in your colors.",
   ("table",[("Editorial","Elegant, with words arriving in polished lockups."),("Heavy","Big and bold, built for social."),("Pill","Classic subtitles in a rounded pill.")]),"Pick the one that feels like you. You can still ask for a different style on any single video later."]),
 ("9. Your defaults",["Portrait for Reels, TikTok and Shorts, landscape for YouTube, or both. Your talking-head style. Your explainer style. And whether you want background music."]),
 ("10. Check the summary",["Everything is saved into two files: your brand file and a plain-English profile. Your assistant reads the summary back and asks if you want to change anything. This is the moment to say yes if something felt off."]),
 ("Changing it later",["Say <b>Change my brand.</b> It shows you what is saved and asks what to update. It never makes you start over."]),
 ],
 check=["I typed Get me set up.","My logo is in the brand folder.","I have my three hex colors.","I chose a metallic finish and a caption style.","I read the saved summary and confirmed it."],
 lesson=dict(
  intro="This is the lesson where you teach the plug-in who you are. You do it one time, and every video after it already looks like you.",
  say=[("Get me set up.","The whole command. It starts the one-time setup."),("Change my brand.","Shows what is saved and asks what to update. It never makes you start over.")],
  know=["Plan on 30 to 60 minutes. You only do this once.","Your logo works best as a PNG with a transparent background, at least 1000 pixels wide.","You choose three brand colors, a metallic finish, a font pairing, who is on screen and a caption style from a side-by-side preview.","Color suggestions from your logo are only suggestions. Nothing is saved until you say yes.","Your setup is saved in a brand file and a plain-English profile. Your assistant reads it back so you can change anything that felt off."]))
L[3]=dict(title="Add your footage and voiceover",sub="Two ways to get your video and your voiceover to your assistant.",
 intro="Your assistant cannot edit what it cannot reach. Start with a clip of 30 to 60 seconds, and keep early tests under about two minutes.",
 steps=[
 ("Method one: your assistant runs on your computer",["This is the easiest. It means Claude Code or Codex on your own machine. You upload nothing.","Open your project folder. Inside it is a folder for raw media (<b>public/raw</b>). Drag your video into it and tell your assistant the file name. Nothing leaves your computer."]),
 ("Method two: your assistant runs in the cloud",["That means Claude Code on the web, a Codex cloud task, or a session started from your phone. A cloud assistant cannot see your computer's files, and chat attachments have size limits most talking-head videos blow past.",
   "1. Upload the video to Google Drive, Dropbox or OneDrive.","2. Set sharing to <b>Anyone with the link can view</b>. In Drive, click Share, change the access, and copy the link.","3. Paste the link into the chat and say: <b>Download this video into my project and edit it.</b>","4. When the edit is done, set sharing back to <b>Restricted</b>.",
   "If the download is blocked, your assistant tells you which web addresses to allow in your environment settings. The Start Here guide lists them."]),
 ("Your voiceover",["For an explainer, your voiceover is the timing for the whole video. The recording matters more than a written script, because the plug-in lines up the pictures with the words you actually said. A script alone cannot tell it when each word happens.","Record in a quiet room at your normal pace and keep one take you are happy with. Save it as an audio file, put it in the raw folder the same way (or share it by link), and say: <b>This is my voiceover. Turn it into an explainer.</b> You will do this in lesson 7."]),
 ("Never share these in chat",["Passwords or private keys, ever."]),
 ("Quick recap",["Small or local: drop it in the raw folder. Cloud assistant: share by link, then set it back to Restricted. And start short."]),
 ],
 check=["I put a short clip in the raw folder and told my assistant its file name.","I know how to share a file by link and set it back to Restricted.","I recorded one voiceover take I like.","I know not to paste passwords or keys into chat."],
 lesson=dict(
  intro="Your assistant cannot edit what it cannot reach. Here are the two ways to get your video and your voiceover to it.",
  say=[("Edit the clip called my-clip.mp4.","Drop your clip in your project's raw media folder first, then tell your assistant its real file name."),("Download this video into my project and edit it.","With a cloud assistant, paste your share link first."),("This is my voiceover. Turn it into an explainer.","Used with your recording. You will do this in lesson 7.")],
  know=["Start with a clip of 30 to 60 seconds. Keep early tests under about two minutes.","If your assistant runs on your computer, drag the video into your project's raw folder. Nothing is uploaded.","If it runs in the cloud, share the video by link from Google Drive, Dropbox or OneDrive, then set sharing back to Restricted when the edit is done.","Your voiceover recording sets the timing of an explainer, because it shows exactly when each word is spoken.","Never paste passwords or private keys into the chat."]))
L[4]=dict(title="Make my video",sub="Your clip goes in and a finished video comes out.",
 intro="Your clip is already in the raw folder. Nothing renders until you approve the storyboard.",
 steps=[
 ("1. The command",["Type: <b>Make my video.</b>"]),
 ("2. Check the transcript",["Before it builds anything, your assistant writes out everything you said and asks you to check it. Please do not skip this. Look for your name, brand names, links and your last line. Voice-to-text sometimes spells a name two ways, or invents a word after the audio ends.","It also checks the ending of your take. If your clip is cut off mid-sentence, it tells you before it edits anything."]),
 ("3. The plan",["It plans the video with your saved style and brand, following editing rules built from real edits: a change on screen at least every four seconds, you stay full frame for about four seconds at a time (six at most), nothing sits on your face, text stays clear of the app buttons, and effects land on the exact word you say."]),
 ("4. The storyboard",["Before anything renders, it shows your whole video as numbered pictures, in order, with the words under each one.","Say <b>Approve</b>, or name the numbers to change: <b>Frame six is too busy, make it simpler.</b> It changes only those parts and makes a new storyboard. You can also say <b>Show me the storyboard</b> any time."]),
 ("5. The checker",["A built-in checker looks for captions covering a graphic, captions that repeat what is already on screen, and effects on the wrong word. It fixes what it finds or tells you why something stays."]),
 ("6. The render",["After you approve, it renders. A video usually takes 30 minutes to an hour, and longer videos take longer. You do not have to watch."]),
 ("7. The check",["When it finishes, it checks the length, the size and whether there is sound, then hands you the video and tells you what it could not check. It can look at pictures but it cannot hear, so you listen to the music and the voice yourself."]),
 ("Changes and batches",["Ask in plain words: <b>Make the captions bigger. Move them to the top. Try the Spotlight style.</b> It never overwrites your old video. It makes a new version.","With several clips, ask for a batch. It makes them one after another, and if one fails it tells you which and keeps going."]),
 ("It never posts for you",["It never posts or schedules anything. The finished video is yours to post."]),
 ],
 check=["I checked the transcript and fixed anything wrong.","I looked at the storyboard and approved it or asked for a change.","I listened to the finished video myself.","I asked for one change and got a new version."],
 lesson=dict(
  intro="This is the lesson where your clip goes in and a finished video comes out. Nothing renders until you approve the storyboard.",
  say=[("Make my video.","Starts the whole workflow on the clip in your raw folder."),("Show me the storyboard.","Your whole video as numbered pictures with the words under each one."),("Frame six is too busy, make it simpler.","Name the numbers you want changed. It changes only those parts."),("Make the captions bigger.","Ask for changes in plain words. You get a new version and keep the first.")],
  know=["Always check the transcript: your name, brand names, links and your last line.","A change on screen at least every four seconds, and effects land on the exact word you say.","You approve the storyboard before anything renders. A video usually takes 30 minutes to an hour to render.","Your assistant can check pictures but cannot hear. You listen to the music and voice yourself.","It never posts or schedules for you."]))
L[9]=dict(title="Stock footage",sub="Optional free B-roll from Pexels and Pixabay, with your own keys. You choose every clip.",
 intro="Everything in the plug-in works without stock footage. If you want B-roll to cut away to, here is how to add it.",
 steps=[
 ("What a key is",["A key is like a library card. It lets the plug-in search for you. Keys are free and take about five minutes each. They stay on your computer. You can use just one provider."]),
 ("1. Pexels key",["Go to <b>pexels.com/api</b> and sign in. Click Your API Key and fill in the short form. The app name can be anything, like My video projects. Copy the key."]),
 ("2. Pixabay key",["Go to <b>pixabay.com/api/docs</b> and sign in. Scroll to Parameters. Your key is shown next to the word key. Copy it."]),
 ("3. Where the keys go",["In your project folder there is a file called stock-keys.example.json. Copy it and name the copy <b>stock-keys.json</b>. Paste each key between the quotes and save.","Then say: <b>Check my stock keys.</b> It tells you set or not set for each. It never prints your keys back.","Never paste your keys into chat, an email or a shared document. If you think one got out, make a new one on the website.","If your assistant runs in the cloud, set the keys as environment secrets instead of a file and allow api.pexels.com, videos.pexels.com, images.pexels.com, pixabay.com and cdn.pixabay.com."]),
 ("4. Find footage",["Say: <b>Find stock footage for this video.</b> It reads your script and turns each shot into a search phrase of two to four concrete words: what is in the frame, not the idea. Woman typing laptop night, not productivity."]),
 ("5. You choose",["It searches both sites and shows the options with where each is from, how long it is, who made it and a link to the clip's page, plus preview images. Open the links to watch the clips. You choose the ones you like."]),
 ("6. Download and place",["Only then does it download, one clip per choice. Each clip is saved into your project and its source and creator are recorded. A clip you choose can fade in as a cutaway over your talking-head video, move, and fade back to you, while your voice keeps playing."]),
 ("7. Credits",["When your video is done, say <b>Show me my stock credits.</b> It gives you a credit line for each clip, ready to paste into your caption or description."]),
 ("Rules to know",["Pixabay results are kept for 24 hours, so the same search within a day does not hit their service again. Clips are downloaded before use, never streamed from the site. The tool never bulk-downloads.","Both sites' licenses allow free use in videos, with limits. For anything sensitive, like an ad with a recognizable person or brand, read the license page yourself and check it again before you publish commercially.","If you see too many requests, wait a little and try again. If a portrait search hides some results, the tool tells you and you can ask to see everything."]),
 ],
 check=["I made a Pexels or Pixabay key.","I put my key in stock-keys.json and ran Check my stock keys.","I searched, looked at the previews and chose a clip.","I saved my stock credits for my caption."],
 lesson=dict(
  intro="Stock footage is optional. If you want B-roll to cut away to, you can add free clips from Pexels and Pixabay, and you choose every one.",
  say=[("Check my stock keys.","Tells you whether each key is set. It never prints your keys."),("Find stock footage for this video.","Reads your script and searches Pexels and Pixabay for each shot."),("Show me my stock credits.","A credit line for every clip you used, ready to paste.")],
  know=["Keys are free and take about five minutes. They stay on your computer. You can use just one provider.","Never paste your keys into chat, email or a shared document.","You see previews, lengths, creators and links, and you choose. Only the clips you choose are downloaded.","A chosen clip can fade in as a cutaway over your talking-head video, then fade back to you, while your voice keeps playing.","Both licenses allow free use in videos with limits. For ads with recognizable people or brands, read the license yourself."]))
L[1]=dict(title="Download, install and open it",sub="Get the plug-in onto your computer, open, and ready to set up.",
 intro="This beta is for a computer with Claude Code or Codex and access to your local files. That means the desktop app or the terminal on your own computer, not the chat in your browser.",
 steps=[
 ("1. Download",["Your files are attached to the first lesson in your course. There are two: the plug-in zip and the Start Here guide. Download both."]),
 ("2. Unzip it",["Put the plug-in in a regular folder on your computer that is <b>not</b> synced to the cloud: not iCloud, not OneDrive and not Dropbox. Cloud sync can stall the install."]),
 ("3. Open the folder in your assistant",["Open that folder in Claude Code or Codex, on your own computer. Open the folder itself."]),
 ("4. Paste the first message",["It is in the Start Here guide and in the course lesson. Paste it and press enter:",
   "<b>Read skills/video-production/SKILL.md and skills/brand-setup/SKILL.md. Get me set up: create a new project folder, check my computer's requirements, then walk me through my brand setup. Explain any missing software in plain language. Do not overwrite existing files.</b>",
   "It tells your assistant to read the plug-in's instructions, create a new project folder, check your computer's requirements and walk you through your brand setup. It never overwrites existing files."]),
 ("5. The requirements check",["The plug-in needs Node 20 or newer, ffmpeg and a browser. If something is missing, your assistant tells you in plain language what it is and what to do. If everything is already installed, the check passes right away."]),
 ("Claude Code or Codex",["It works the same way in both. Open the folder, paste the same message, and your assistant takes it from there."]),
 ("What happens next",["Your first setup takes 30 to 60 minutes, and you only do it once. That is lesson 2."]),
 ("If you get stuck",["Email support@c3global.co with what you asked and the exact error. Never include passwords or API keys."]),
 ],
 check=["I downloaded the plug-in zip and the Start Here guide.","I unzipped the plug-in into a folder that is not cloud-synced.","I opened that folder in Claude Code or Codex on my own computer.","I pasted the first message and the requirements check ran."],
 lesson=dict(intro="",say=[],know=[]))
